def leafAddress (t : RMAF.Tree) (x : Nat) : Vertex := (leafList [x] t).headD []

def descendants (t : RMAF.Tree) (v : Vertex) : List Nat :=
  (RMAF.leaves t).filter (fun x => prefixB v (leafAddress t x))

def sideLabels (A : List Nat) (t : RMAF.Tree) (v : Vertex) (inside : Bool) : List Nat :=
  A.filter (fun x => if inside then (descendants t v).contains x else !((descendants t v).contains x))

def taggedColor (A B : List Nat) (ca cb cc : Nat → Nat) (x : Nat) : Nat :=
  if x ∈ A then 3 * ca x else if x ∈ B then 3 * cb x + 1 else 3 * cc x + 2

def localColors (D : List Nat) (f : Nat → Nat) : List Nat := dedupNat (D.map f)

def sideColor (D : List Nat) (x : Nat) : Nat := if x ∈ D then 0 else 1

def sideOutputs (S : Tree) (A B D : List Nat) (q : Nat) : List Output :=
  WholeSourceMass.wholeOutputs S A B (fun _ => 0) (sideColor D) (fun _ => 0) q
